"""Tests for subject.extract_imports."""

from subject import extract_imports


def test_plain_import_returns_single_name():
    assert extract_imports("import os") == ["os"]


def test_dotted_import_returns_full_path():
    assert extract_imports("import foo.bar") == ["foo.bar"]


def test_deeply_dotted_import_returns_full_path():
    assert extract_imports("import a.b.c.d") == ["a.b.c.d"]


def test_from_import_returns_module_not_imported_name():
    assert extract_imports("from os import path") == ["os"]


def test_dotted_from_import_returns_full_path():
    assert extract_imports("from foo.bar import baz") == ["foo.bar"]


def test_deeply_dotted_from_import_returns_full_path():
    assert extract_imports("from a.b.c import thing") == ["a.b.c"]


def test_aliased_dotted_import_returns_full_path():
    assert extract_imports("import numpy.fft as fft") == ["numpy.fft"]


def test_aliased_from_import_returns_full_path():
    assert extract_imports("from foo.bar import baz as qux") == ["foo.bar"]


def test_multiple_names_in_one_import_statement():
    assert extract_imports("import alpha, beta.gamma") == ["alpha", "beta.gamma"]


def test_from_import_with_multiple_names_yields_one_entry():
    assert extract_imports("from foo import bar, baz") == ["foo"]


def test_mixed_top_level_statements_preserve_order():
    source = "import one.two\nfrom three.four import five\nimport six"
    assert extract_imports(source) == ["one.two", "three.four", "six"]


def test_import_inside_function_is_found():
    source = "def f():\n    import x.y\n    return 1\n"
    assert extract_imports(source) == ["x.y"]


def test_imports_in_nested_blocks_are_found():
    source = (
        "class C:\n"
        "    def m(self):\n"
        "        from p.q.r import s\n"
        "        return s\n"
        "\n"
        "try:\n"
        "    import t.u\n"
        "except ImportError:\n"
        "    pass\n"
    )
    assert sorted(extract_imports(source)) == ["p.q.r", "t.u"]


def test_duplicate_imports_are_not_deduplicated():
    assert extract_imports("import foo.bar\nimport foo.bar") == ["foo.bar", "foo.bar"]


def test_relative_import_without_module_yields_nothing():
    assert extract_imports("from . import sibling") == []


def test_source_without_imports_returns_empty_list():
    assert extract_imports("x = 1\ny = x + 2\nprint(y)\n") == []


def test_empty_source_returns_empty_list():
    assert extract_imports("") == []


def test_comment_only_source_returns_empty_list():
    assert extract_imports("# just a comment\n") == []


def test_invalid_syntax_returns_empty_list():
    assert extract_imports("def (") == []


def test_incomplete_import_returns_empty_list():
    assert extract_imports("import") == []
